  "catalog.tool_guides.wifi_qr.tips.0": "Double-check capitalization in the network name and password.",
  "catalog.tool_guides.wifi_qr.tips.1": "Do not print the password in plain text if you want visitors to scan only.",
  "catalog.tool_guides.wifi_qr.common_mistakes.0": "Entering the wrong network name or password.",
  "catalog.tool_guides.wifi_qr.common_mistakes.1": "Choosing a security type that does not match the network.",
  "catalog.tool_guides.wifi_qr.faqs.0.question": "Is a Wi-Fi QR code safe?",
  "catalog.tool_guides.wifi_qr.faqs.0.answer": "It is as safe as sharing the Wi-Fi password. Anyone who can scan the code may be able to join, so place it only where intended guests can access it.",
